_THIS_PARENT_DIR = os.path.dirname(_THIS_FILE_DIR)
_LOCAL_MODULE_DIRS = [
    _THIS_FILE_DIR,
    _THIS_PARENT_DIR,
    os.path.join(_THIS_FILE_DIR, "undistort"),
    os.path.join(_THIS_PARENT_DIR, "undistort"),
]
