def _resolve_runtime_file(path_value: str) -> str:
    """Resolve a relative file from either dual/ or dual/undistort/."""
    raw = os.path.expanduser(str(path_value or ""))
    if not raw or os.path.isabs(raw) or os.path.exists(raw):
        return raw
    candidates = [
        os.path.join(_THIS_FILE_DIR, raw),
        os.path.join(_THIS_PARENT_DIR, raw),
        os.path.join(_THIS_FILE_DIR, "undistort", raw),
        os.path.join(_THIS_PARENT_DIR, "undistort", raw),
    ]
    for candidate in candidates:
        if os.path.isfile(candidate):
            return os.path.abspath(candidate)
    return raw

