class RoArmSerial:
    """Minimal RoArm serial wrapper compatible with Waveshare JSON serial commands."""

    def __init__(self, port: str, baudrate: int = 115200, label: str = "arm"):
        if serial is None:
            raise RuntimeError("pyserial is not installed. Run: pip3 install pyserial")
        self.port = port
        self.label = label
        self.ser = serial.Serial(port, baudrate=baudrate, timeout=0.15)
        try:
            self.ser.setDTR(False)
            self.ser.setRTS(False)
        except Exception:
            pass
        time.sleep(0.5)

    def send(
        self,
        cmd: Dict[str, Any],
        delay: float = 0.18,
        stage: Optional[str] = None,
        caller: Optional[str] = None,
        log_command: bool = True,
    ) -> None:
        """Write one JSON command at the final serial boundary.

        Existing callers retain the original 0.18 s delay and terminal logging.
        D37-v4's high-rate laydown stream explicitly passes delay=0 and disables
        per-waypoint logging so Python sleeps/printing cannot pause the trajectory.
        """
        line = json.dumps(cmd, separators=(",", ":"))
        if bool(log_command):
            print(
                f"[SERIAL-CMD {time.monotonic():.6f}] "
                f"thread={threading.current_thread().name} arm={self.label} "
                f"port={self.port} T={int(cmd.get('T', -1))} "
                f"stage={stage or '-'} caller={caller or '-'} payload={line}"
            )
        self.ser.write((line + "\n").encode("utf-8"))
        self.ser.flush()
        if float(delay) > 0.0:
            time.sleep(float(delay))

    def move_goal(
        self,
        x: float,
        y: float,
        z: float,
        t: float,
        spd: float,
        move_command: int = 104,
        stage: Optional[str] = None,
        caller: Optional[str] = None,
        delay: float = 0.18,
        log_command: bool = True,
    ) -> None:
        self.send(
            {"T": int(move_command), "x": float(x), "y": float(y), "z": float(z), "t": float(t), "spd": float(spd)},
            delay=delay, stage=stage, caller=caller, log_command=log_command,
        )

    def move_direct(
        self,
        x: float,
        y: float,
        z: float,
        t: float,
        stage: Optional[str] = None,
        caller: Optional[str] = None,
        delay: float = 0.0,
        log_command: bool = False,
    ) -> None:
        """Send one non-blocking direct Cartesian target (T:1041).

        T:1041 does not use the T:104 ``spd`` field.  D50 controls effective
        speed by target spacing and a fixed host-side stream period.
        """
        self.send(
            {
                "T": 1041,
                "x": float(x),
                "y": float(y),
                "z": float(z),
                "t": float(t),
            },
            delay=delay, stage=stage, caller=caller, log_command=log_command,
        )

    def set_gripper(
        self,
        angle_rad: float,
        delay: float = 0.25,
        stage: Optional[str] = None,
        caller: Optional[str] = None,
    ) -> None:
        self.send(
            {"T": 106, "cmd": float(angle_rad), "spd": 0, "acc": 0},
            delay=delay, stage=stage, caller=caller,
        )

    def close(self) -> None:
        try:
            self.ser.close()
        except Exception:
            pass


